-- 172_school_intro_backfill_round5.sql
-- 院校简介回填（第 172 批，2026-11-24）：第五批 11 所「官网可查、简介为空」院校。
--
-- 口径同 168-171：只用院校官网自述页原文，逐字摘录，200-500 字，句末截断；
-- 仅当 intro 为空时更新，重复执行不覆盖既有简介；不物理删除。
-- 证据：backfill_local/out/school_intro_172_evidence.csv
--
-- 方法：先检索定位各校官网「学校简介/学院概况」页，再用阅读器式抓取取正文
-- （避免脚本请求被 412/JS 壳拦截）；#831 取官网「中央团校（中国青年政治学院）简介」页。
--
-- 仍未处理（原因）：
--   #25/#26/#202/#264/#536 机械总院各所：官网统一跳转集团站，无各所独立简介，不混用；
--   #30/#183 中国兵器科学研究院各所：站内仅新闻流，无简介页；
--   #163 山西大同大学：云端返回 403「请添加路由白名单」；#834 北京警察学院：503；
--   #780 空军工程大学：官网当前不可达；#897 黑龙江工业学院：官网无简介栏目，仅有第三方库资料；
--   #1065 甘肃民族师范学院：官网当前不可达；
--   中科院各所/社科院/央企研究院：#1083-#1152 等尚无 official_url，待补官网后再取证。

UPDATE kaoyan_schools AS s
SET intro = v.intro,
    updated_at = now()
FROM (VALUES
    (830, '北京联合大学是一所集经济学、法学、教育学、文学、历史学、理学、工学、医学、管理学、艺术学、交叉学科等多学科协调发展的综合性大学，也是北京市最大的市属综合性大学，是北京市重点建设的高水平应用型大学和北京市应用型人才培养的重要基地。学校前身是1978年北京大学、清华大学、中国人民大学、北京师范大学、北京航空航天大学、北京理工大学等创办的36所大学分校。1985年，依托大学分校，经教育部批准成立北京联合大学。2006年，学校开展硕士研究生教育；2024年，学校获批博士学位授予单位；2025年，学校获批教育部新增推荐优秀应届本科毕业生免试攻读硕士研究生（推免）资格。学校坚持“学以致用”的校训，秉承“发展应用型教育、培养应用型人才、建设应用型大学”的办学宗旨，立足北京、面向京津冀、辐射全国、放眼世界，面向应用、面向需求、面向社会，努力培养知行合一、学以致用、具有创新精神的优秀应用型建设人才。'),
    (831, '中央团校创建于1948年9月，其前身可以追溯到1932年12月在江西瑞金创办的列宁团校，与鲁迅青年学校、安吴青训班、泽东青年干部学校同根同源，具有红色基因、悠久历史和光荣传统。1985年9月，在中央团校基础上命名组建了中国青年政治学院，2012年起由团中央和教育部共建。学校2003年获得硕士学位授予权。改革后，继续以中国青年政治学院名义举办研究生教育，发挥其在师资涵养、学科建设、学理支撑、国际交流等方面作用。学校现设有马克思主义理论等一级学科硕士点和社会工作等专业型硕士学位授权点，2018年入选北京市博士学位授予立项建设单位。'),
    (842, '衡水学院坐落于河北省衡水市，是一所由省市政府共建、以市管为主的全日制普通本科高校。学校办学历史悠久，教育体系完整，始终秉承“守正出新”的校训，坚持“立德树人”根本任务，致力于建设具有鲜明地方特色的高水平应用型大学。学校前身为创办于1923年的直隶省立第六师范学校，历经省立冀县师范学校、衡水师范专科学校等多个发展阶段，于2004年升格为本科院校并更名为衡水学院。百年办学历程中，学校实现了从专科到本科、从师范到多科、从多科到应用、从外延到内涵的跨越式发展，为区域经济社会发展作出了重要贡献。2008年获得学士学位授予权，2015年通过教育部本科教学工作合格评估，2020年被确立为河北省应用转型发展试点高校，2023年顺利完成本科教育教学审核评估，2024年入选河北省硕士学位立项建设重点培育单位。学校现拥有两个校区，总占地面积2479亩。现有全日制在校生1.67万人。'),
    (844, '邯郸学院是一所公办全日制普通本科院校，位于国家历史文化名城、国家优秀旅游城市、太极拳圣地、成语典故之都河北省邯郸市，系全国绿化先进单位、教育部第一批全国普通高校中华优秀传统文化传承基地、河北省文明校园。办学历史始于1905年成立的邯郸县初级师范学堂，1982年升格为邯郸师范专科学校，2004年升格为本科院校并定名为邯郸学院，2016年被列为河北省硕士学位授予权立项建设单位，2021年确定为河北省第二批转型发展试点院校，2024年在邯郸市经开区联办两所附属小学，2025年接收设立邯郸学院附属高级中学，实现大中小学办学功能一体贯通。学校现有在职教职工1314人，教授、副教授356人，博士、硕士1058人。全日制本科在校生16746人，成人学历教育学生4715人。设有21个二级学院（系部），在招本科专业48个，涉及十大学科门类。校园占地1193亩，学校教学科研仪器设备资产总值2.6亿元，纸质图书171.02万册。'),
    (879, '辽宁警察学院是全省唯一一所省属全日制公安本科院校，肩负着为全省公安司法机关培养应用型警务人才、培训在职民警的双重历史重任。2014年5月经教育部批准正式建立，前身为辽宁警官高等专科学校，学校创建于1960年，1985年建立大专，1995年开始独立试办本科专业。建校以来，已经为全省公安、司法等系统培养了4万多名优秀警务专门人才。学院位于大连市甘井子区营平路，校园占地59万平方米，分院位于鞍山市铁东区千山中路，占地面积7.8万平方米。学院设置侦查学、刑事科学技术、治安学、网络安全与执法、交通管理工程、经济犯罪侦查、警务指挥与战术、公安视听技术、犯罪学、监狱学10个公安司法类本科专业，交通管理、航空服务艺术与管理2个普通类专业。目前，我院网络安全与执法、治安学入选国家级一流本科专业建设点。学院有教职工编制580人，其中正高级49人，副高级123人，硕士研究生以上229人，现有全日制在校生5335人。'),
    (885, '通化师范学院坐落在长白山脚下、鸭绿江畔，是吉林省东南部唯一一所省属本科院校，同时也是一所拥有悠久办学历史和光荣革命传统的国门大学。学校发端于1906年（光绪三十二年）创立的通化师范讲习所，先后易名为辽宁省立通化师范学校、奉天省立第六师范学校、安东省立第六师范学校、通化省立通化师范学校、辽东省立通化师范学校，1958年改为通化师范专科学校，1978年经国家教育部批准正式升格为普通本科院校，更名为通化师范学院。学校秉承“崇德广业、与时偕行”的校训，坚守“质朴的教育”理念，弘扬以“靖宇精神建校育人”的办学传统，坚持“一魂一师一山一城一族一史”的办学优势，彰显“三地三前沿”的办学特色。学校主校区占地49万平方米，建筑面积23万平方米，有14个教学单位，教职员工1105人，全日制在校生13448人，继续教育学生9322人，面向全国29个省区市招生。学校设50个专业，涵盖10个学科门类。'),
    (902, '上海公安学院是上海市唯一一所培养高素质应用型警务人才的公安本科院校，由上海市人民政府举办，市公安局主管，接受市教委业务指导。学院前身是解放战争时期中国共产党创办的华东警官学校。1949年6月，成立上海市警务学校，历经中央人民公安学院上海分院、上海市公安学校、上海公安专科学校等阶段，2016年升为上海公安学院。学院现有浦东、闵行2个校区，占地面积685.4亩；教职工400余人，其中专任教师190余人。学院聚焦公安学和公安技术2个学科，开设治安学、侦查学、警务指挥与战术、刑事科学技术、网络安全与执法、数据警务技术、安全防范工程7个本科专业，侦查学和网络安全与执法2个专业入选上海市一流本科专业建设点。'),
    (926, '浙江音乐学院是教育部于2016年3月1日批准成立的公办全日制普通高校。由浙江省人民政府举办，浙江省人民政府与文化和旅游部实施共建。学校坐落于杭州市西湖区之江板块，校园环境优美，设施一流。校园占地面积602亩，校舍建筑面积36万平方米。拥有大剧院1座、音乐厅3座、剧场3个、演播厅2个、排练厅104间、琴房935间、录音棚8间以及图书馆等教学辅助和艺术实践场馆。学校设有音乐与舞蹈学、艺术学理论、戏剧与影视学等3个一级学科，音乐与舞蹈学学科被列为省一流学科A类建设计划，戏剧与影视学、艺术学理论被列为省一流学科B类建设计划。学校经教育部批准具有参照独立设置本科艺术院校艺术类专业单独招生资格，面向全国招生。现有在校本科生2909人，研究生674人，留学生49人。现有教职工806人，其中专任教师520人。'),
    (988, '郑州警察学院是公安部直属、面向全国公安机关，聚焦铁路、城市轨道交通系统办学，服务国家安全战略，坚持内涵发展、特色发展、创新发展，着力打造适应公安工作现代化需要的优秀人才培养高地、警务科技创新高地和服务实战支撑高地，努力建成特色鲜明、学科专业优势突出的一流公安院校，1950年创建于北京，1980年迁建郑州，2000年从原铁道部划归公安部管理，2013年经教育部批准独立举办全日制普通本科教育，更名为铁道警察学院，2023年落实中央全面深化改革精神，更名为郑州警察学院。现有龙湖和农业路两个校区，校园占地面积931.23亩。设置有治安学、侦查学、公安管理学、刑事科学技术、网络安全与执法、铁路警务、警务指挥与战术7个本科专业和治安学专业城轨安全与执法1个专业方向，覆盖法学、工学2个学科门类。5个专业入选国家级一流本科专业建设点。'),
    (1034, '成都大学创建于1978年，是改革开放后首批地方城市主办的全日制普通本科院校。学校实行省市共建、以市为主的办学体制，是四川省、成都市重点建设大学，是第31届世界大学生夏季运动会运动员村承办大学，FISU银级认证“健康校园”。拥有百年历史的三级甲等综合附属医院和国家级科研平台四川抗菌素工业研究所。学校办学历史悠久，可追溯至1906年的公立四川优级选科师范学堂和1911年的公立四川省城女子师范学堂。现具有学士、硕士学位授予权，设有博士后实践基地，是教育部“卓越工程师教育培养计划”高校、教育部国防教育特色高校、教育部“双万计划”一流本科专业建设点立项单位、四川省“优先培育”类博士学位授予立项建设单位。学校设有经济学、法学、教育学、文学、理学、工学、农学、医学、管理学、艺术学、交叉学科11个学科门类，75个本科专业；现有硕士学位授权点28个。'),
    (1062, '陕西学前师范学院是一所以教师教育为主、以培养学前教育师资为特色的省属公办普通本科院校。学校前身为陕西教育学院，1963年由陕西省西安师范学校（1906年建立）和陕西省教师进修学校（1956年建立）合并成立。2012年3月，经教育部批准，改制更名为陕西学前师范学院，是目前全国唯一以“学前师范”命名的本科院校。学校秉承“厚德博学”的校训和“立身传道，自强不息，大气大度，止于至善”的办学精神，坚持“师范性、地方性、应用型”的办学定位，突出学前教育和教师教育特色与优势，扎实推进转型发展、内涵发展和特色发展，积极构建“价值塑造、知识传授、能力培养、素质提升、实践锻炼”五位一体的人才培养体系，走出了一条具有自身特色的发展道路。学校位于历史文化名城古都西安，现有长安、雁塔2个校区，图书馆藏有纸质图书177.5万册，电子图书146.82万册。')
) AS v(id, intro)
WHERE s.id = v.id
  AND (s.intro IS NULL OR btrim(s.intro) = '');
